  p1: vec4f, // focusDist, focusRange, dof, vignette
  p2: vec4f, // aberration, saturation, contrast, grain
  p3: vec4f, // tint rgb, letterbox
  p4: vec4f, // flash rgba
  p5: vec4f, // near, far, fullW, fullH
  p6: vec4f, // fog rgb, density
